function fotosDe(cod) {
    var lista = [];
    var nombres = FOTOS[cod];

    if (nombres == undefined) {
        return lista;
    }

    for (var i = 0; i < nombres.length; i++) {
        var nombre = nombres[i];

        if (nombre.indexOf("_") == -1) {
            nombre = PREFIJO + nombre;
        }

        lista.push(RUTA + cod + "/" + nombre + ".webp");
    }

    return lista;
}